class Dsu {
    readonly int[] parent, size;
    public int Count;                                  // сколько сейчас групп
    public Dsu(int n) {
        parent = new int[n]; size = new int[n]; Count = n;
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
    }
    public int Find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];             // сжатие: прыжок через одного
            x = parent[x];
        }
        return x;
    }
    public bool Union(int a, int b) {
        int ra = Find(a), rb = Find(b);
        if (ra == rb) return false;                    // уже вместе: ребро лишнее
        if (size[ra] < size[rb]) (ra, rb) = (rb, ra);  // меньшее — под большее
        parent[rb] = ra;
        size[ra] += size[rb];
        Count--;
        return true;
    }
}

