public int MinCostConnectPoints(int[][] points) {
    int n = points.Length;
    var edges = new List<(int w, int a, int b)>(n * (n - 1) / 2);
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            edges.Add((Math.Abs(points[i][0] - points[j][0]) + Math.Abs(points[i][1] - points[j][1]), i, j));
    edges.Sort();                                   // кортежи сравниваются сначала по весу
    var dsu = new Dsu(n);
    int total = 0;
    foreach (var (w, a, b) in edges) {
        if (!dsu.Union(a, b)) continue;             // уже в одной группе — ребро дало бы цикл
        total += w;
        if (dsu.Count == 1) break;                  // n − 1 рёбер взяты
    }
    return total;
}
